/**
 * Yaven brand mark — the 3D prism logo (cream / rainbow / navy), inlined so
 * it renders anywhere with no asset pipeline. Same image the site ships at
 * /yaven-logo.webp.
 * @category brand
 */
export function YavenLogo({
  height = 52,
  alt = "Yaven",
  className,
  style
}: {
  /** Rendered height (px number or any CSS length). Width scales to keep the mark's aspect. */
  height?: number | string
  alt?: string
  className?: string
  style?: React.CSSProperties
}) {
  const h = typeof height === "number" ? height + "px" : height
  return (
    <img
      src={LOGO_SRC}
      alt={alt}
      className={className}
      style={{ height: h, width: "auto", objectFit: "contain", display: "inline-block", ...style }}
    />
  )
}

const LOGO_SRC =
  "data:image/webp;base64,"
